import React, { useEffect, useRef } from 'react';

const BeastAnimation: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mouse = useRef({ x: 0, y: 0 });
  const isHovering = useRef(false);

  // Segment configuration
  const numSegments = 20;
  const segments = useRef(Array.from({ length: numSegments }, () => ({ x: 0, y: 0 })));

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const handleResize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };

    const handleMouseMove = (e: MouseEvent) => {
      mouse.current.x = e.clientX;
      mouse.current.y = e.clientY;

      // Check if hovering interactive elements
      const target = e.target as HTMLElement;
      isHovering.current = !!target.closest('button, a, .cursor-pointer');
    };

    const handleMouseDown = () => {
      // Impact effect: push segments apart slightly
      segments.current.forEach(seg => {
        seg.x += (Math.random() - 0.5) * 50;
        seg.y += (Math.random() - 0.5) * 50;
      });
    };

    window.addEventListener('resize', handleResize);
    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('mousedown', handleMouseDown);
    handleResize();

    let animationFrame: number;
    const render = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);

      // Physics: First segment follows mouse
      const head = segments.current[0];
      head.x += (mouse.current.x - head.x) * 0.25;
      head.y += (mouse.current.y - head.y) * 0.25;

      // Other segments follow previous with decay
      for (let i = 1; i < numSegments; i++) {
        const seg = segments.current[i];
        const prev = segments.current[i - 1];

        // Organic lag effect
        const dx = prev.x - seg.x;
        const dy = prev.y - seg.y;
        seg.x += dx * 0.35;
        seg.y += dy * 0.35;
      }

      // Draw the "Beast"
      ctx.lineCap = 'round';
      ctx.lineJoin = 'round';

      // Draw shadow trail
      ctx.beginPath();
      ctx.moveTo(segments.current[0].x, segments.current[0].y);
      for (let i = 1; i < numSegments; i++) {
        ctx.lineTo(segments.current[i].x, segments.current[i].y);
      }

      const gradient = ctx.createLinearGradient(
        segments.current[0].x, segments.current[0].y,
        segments.current[numSegments-1].x, segments.current[numSegments-1].y
      );

      const mainColor = isHovering.current ? '252, 211, 77' : '16, 185, 129'; // Gold vs Emerald
      gradient.addColorStop(0, `rgba(${mainColor}, 0.6)`);
      gradient.addColorStop(1, `rgba(${mainColor}, 0)`);

      ctx.strokeStyle = gradient;
      ctx.lineWidth = isHovering.current ? 12 : 6;
      ctx.stroke();

      // Draw glowing segments
      segments.current.forEach((seg, i) => {
        const size = (numSegments - i) * (isHovering.current ? 1.5 : 1.2);
        const opacity = (numSegments - i) / numSegments * 0.3;

        ctx.beginPath();
        ctx.arc(seg.x, seg.y, size, 0, Math.PI * 2);
        ctx.fillStyle = `rgba(${mainColor}, ${opacity})`;
        ctx.fill();

        if (i === 0) { // Head glow
          ctx.beginPath();
          ctx.arc(seg.x, seg.y, size * 2, 0, Math.PI * 2);
          const headGrad = ctx.createRadialGradient(seg.x, seg.y, 0, seg.x, seg.y, size * 2);
          headGrad.addColorStop(0, `rgba(${mainColor}, 0.2)`);
          headGrad.addColorStop(1, `rgba(${mainColor}, 0)`);
          ctx.fillStyle = headGrad;
          ctx.fill();
        }
      });

      animationFrame = requestAnimationFrame(render);
    };

    render();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mousedown', handleMouseDown);
      cancelAnimationFrame(animationFrame);
    };
  }, []);

  return (
    <canvas
      ref={canvasRef}
      className="fixed inset-0 pointer-events-none z-[150] mix-blend-screen opacity-70"
      style={{ filter: 'blur(1px)' }}
    />
  );
};

export default BeastAnimation;

