import React, { useState, useRef } from 'react';
import { analyzeWildlife, generateSafariImage } from '../services/geminiService';
import { WildlifeAnalysis } from '../types';
import Chatbot from './Chatbot';

const AILab: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [preview, setPreview] = useState<string | null>(null);
  const [analysis, setAnalysis] = useState<WildlifeAnalysis | null>(null);
  const [loading, setLoading] = useState(false);
  const [generatedImage, setGeneratedImage] = useState<string | null>(null);
  const [imagePrompt, setImagePrompt] = useState('');
  const [generating, setGenerating] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0];
    if (f) {
      setFile(f);
      const reader = new FileReader();
      reader.onloadend = () => setPreview(reader.result as string);
      reader.readAsDataURL(f);
      setAnalysis(null);
    }
  };

  const handleAnalyze = async () => {
    if (!preview) return;
    setLoading(true);
    try {
      const base64 = preview.split(',')[1];
      const result = await analyzeWildlife(base64);
      setAnalysis(result);
    } catch (e) {
      console.error(e);
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateImage = async () => {
    if (!imagePrompt.trim()) return;
    setGenerating(true);
    try {
      const img = await generateSafariImage(imagePrompt);
      setGeneratedImage(img);
    } catch (e) {
      console.error(e);
    } finally {
      setGenerating(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#022C22] pt-32 pb-20 px-6">
      <div className="container mx-auto max-w-7xl">
        <div className="text-center mb-20">
          <h1 className="text-5xl md:text-7xl font-serif text-white mb-6">AI Wild Lab</h1>
          <p className="text-emerald-400 font-bold tracking-[0.5em] uppercase text-xs opacity-60">Advanced Jungle Intelligence</p>
        </div>

        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 mb-20">
          {/* Wildlife Identification */}
          <div className="bg-[#064E3B] rounded-3xl p-8 border border-white/5 shadow-2xl">
            <div className="flex items-center gap-4 mb-8">
              <div className="w-12 h-12 rounded-2xl bg-emerald-500/20 flex items-center justify-center text-emerald-400">
                <i className="fa-solid fa-camera-retro text-2xl"></i>
              </div>
              <h2 className="text-2xl font-serif text-white">Wildlife ID</h2>
            </div>

            <div 
              onClick={() => fileInputRef.current?.click()}
              className="aspect-video bg-black/20 rounded-2xl border-2 border-dashed border-white/10 flex flex-col items-center justify-center cursor-pointer hover:border-emerald-500/50 transition-all overflow-hidden group mb-6"
            >
              {preview ? (
                <img src={preview} className="w-full h-full object-cover group-hover:scale-105 transition-transform" alt="Preview" />
              ) : (
                <div className="text-center p-10">
                  <i className="fa-solid fa-cloud-arrow-up text-4xl text-white/20 mb-4"></i>
                  <p className="text-white/40 text-sm font-medium">Click to upload wildlife photo</p>
                </div>
              )}
              <input ref={fileInputRef} type="file" accept="image/*" onChange={handleFileChange} className="hidden" />
            </div>

            <button 
              onClick={handleAnalyze}
              disabled={!preview || loading}
              className={`w-full py-5 rounded-2xl font-bold uppercase tracking-[0.3em] text-xs transition-all ${
                preview && !loading ? 'bg-emerald-500 text-white hover:bg-emerald-400 shadow-xl' : 'bg-white/5 text-white/20'
              }`}
            >
              {loading ? <i className="fa-solid fa-spinner animate-spin mr-2"></i> : <i className="fa-solid fa-bolt mr-2"></i>}
              Analyze Species
            </button>

            {analysis && (
              <div className="mt-8 space-y-4 animate-fade-in-down">
                <div className="p-6 bg-white/5 rounded-2xl border border-white/5">
                  <h3 className="text-emerald-400 font-bold uppercase tracking-widest text-[10px] mb-2">Species Identified</h3>
                  <p className="text-xl font-serif text-white">{analysis.species}</p>
                </div>
                <div className="grid grid-cols-2 gap-4">
                  <div className="p-4 bg-white/5 rounded-xl">
                    <p className="text-[9px] uppercase font-bold text-white/40 mb-1">Status</p>
                    <p className="text-xs text-white/80">{analysis.conservationStatus}</p>
                  </div>
                  <div className="p-4 bg-white/5 rounded-xl">
                    <p className="text-[9px] uppercase font-bold text-white/40 mb-1">Habitat</p>
                    <p className="text-xs text-white/80">{analysis.habitat}</p>
                  </div>
                </div>
                <div className="p-6 bg-emerald-900/40 rounded-2xl border border-emerald-500/20">
                  <p className="text-xs italic text-emerald-200 leading-relaxed">"{analysis.funFact}"</p>
                </div>
              </div>
            )}
          </div>

          {/* Safari AI Guide */}
          <Chatbot />
        </div>

        {/* Visualizer Section */}
        <div className="bg-white/5 rounded-3xl p-10 border border-white/5">
          <div className="flex flex-col md:flex-row items-center justify-between gap-10">
            <div className="w-full md:w-1/2">
              <h2 className="text-4xl font-serif text-white mb-6">Dream Your Safari</h2>
              <p className="text-white/60 font-light leading-relaxed mb-8">
                Describe your ideal wildlife encounter and our generative engine will visualize it in 4K resolution using native Wilpattu textures.
              </p>
              <div className="flex gap-4">
                <input 
                  type="text" 
                  value={imagePrompt}
                  onChange={(e) => setImagePrompt(e.target.value)}
                  placeholder="e.g. A leopard drinking at the edge of Kokkare Villu..."
                  className="flex-1 bg-[#064E3B] border border-white/10 rounded-2xl px-6 py-4 text-white outline-none focus:border-emerald-400"
                />
                <button 
                  onClick={handleGenerateImage}
                  disabled={generating}
                  className="bg-white text-[#022C22] px-8 rounded-2xl font-bold text-xs uppercase tracking-widest hover:bg-emerald-400 transition-all shadow-2xl"
                >
                  {generating ? '...' : 'Visualize'}
                </button>
              </div>
            </div>
            <div className="w-full md:w-1/2 aspect-video bg-black/40 rounded-2xl overflow-hidden shadow-2xl border border-white/5">
              {generatedImage ? (
                <img src={generatedImage} className="w-full h-full object-cover animate-pulse" alt="Generated" />
              ) : (
                <div className="w-full h-full flex flex-col items-center justify-center text-white/10">
                  <i className="fa-solid fa-wand-magic-sparkles text-6xl mb-4"></i>
                  <p className="text-sm">Enter a prompt to visualize</p>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AILab;

