      {/* Floating Buttons */}
      <div className="fixed bottom-10 right-10 flex flex-col gap-6 z-[200]">
        <div 
          onClick={() => setActiveSection(AppSection.SPEAK_TO_GOD)} 
          className="w-16 h-16 bg-white text-[#064E3B] rounded-full flex items-center justify-center text-2xl shadow-[0_20px_40px_-10px_rgba(0,0,0,0.5)] hover:scale-110 hover:-translate-y-2 cursor-pointer border-2 border-emerald-500 transition-all group"
        >
            <i className="fa-solid fa-om group-hover:animate-spin-slow"></i>
            <span className="absolute right-full mr-4 bg-emerald-600 text-white text-[10px] font-bold py-2 px-4 rounded-full opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap shadow-xl">SPEAK TO GOD</span>
        </div>
        <div onClick={() => setActiveSection(AppSection.AI_TOOLS)} className="w-14 h-14 bg-emerald-600 rounded-full flex items-center justify-center text-white text-xl shadow-2xl hover:scale-110 cursor-pointer border-2 border-white group">
            <i className="fa-solid fa-sparkles"></i>
            <span className="absolute right-full mr-4 bg-emerald-700 text-white text-[10px] font-bold py-2 px-4 rounded-full opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap shadow-xl">AI LAB</span>
