const ScrollingGallery: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [isPaused, setIsPaused] = useState(false);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });
  const [isHovering, setIsHovering] = useState(false);
  const requestRef = useRef<number>(0);
  const scrollX = useRef(0);

  const animate = () => {
    if (!isPaused && scrollRef.current) {
      scrollX.current += 1; // Speed of scroll
      if (scrollX.current >= scrollRef.current.scrollWidth / 2) {
        scrollX.current = 0;
      }
      scrollRef.current.style.transform = `translateX(-${scrollX.current}px)`;
    }
    requestRef.current = requestAnimationFrame(animate);
  };

  useEffect(() => {
    requestRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(requestRef.current);
  }, [isPaused]);

  const handleMouseMove = (e: React.MouseEvent) => {
    if (containerRef.current) {
      const rect = containerRef.current.getBoundingClientRect();
      setMousePos({
        x: e.clientX - rect.left,
        y: e.clientY - rect.top,
      });
    }
  };

  return (
    <div 
      ref={containerRef}
      className="relative w-full overflow-hidden bg-[#022C22] py-32 cursor-none border-t border-white/5"
      onMouseMove={handleMouseMove}
      onMouseEnter={() => setIsHovering(true)}
      onMouseLeave={() => {
        setIsHovering(false);
        setIsPaused(false);
      }}
      onMouseDown={() => setIsPaused(true)}
      onMouseUp={() => setIsPaused(false)}
    >
      {/* Blinking Text Effect Cursor */}
      <div 
        className={`fixed pointer-events-none z-[160] flex flex-col items-center justify-center transition-opacity duration-300 ${isHovering ? 'opacity-100' : 'opacity-0'}`}
        style={{ 
          left: `${mousePos.x + (containerRef.current?.getBoundingClientRect().left || 0)}px`, 
          top: `${mousePos.y + (containerRef.current?.getBoundingClientRect().top || 0)}px`,
          transform: `translate(-50%, -50%)`
        }}
      >
        <div className={`flex flex-col items-center justify-center transition-transform duration-200 ${isPaused ? 'scale-75' : 'scale-100'}`}>
          <div className="text-emerald-400 text-[12px] font-bold tracking-[0.5em] uppercase mb-1 drop-shadow-[0_2px_10px_rgba(0,0,0,0.5)] animate-pulse">
            {isPaused ? 'PAUSED' : 'DRAG ME'}
          </div>
          <div className="w-8 h-[1px] bg-emerald-400 opacity-50 animate-pulse"></div>
          <div className="mt-2 flex gap-1 animate-pulse">
            <i className="fa-solid fa-chevron-left text-[8px] text-emerald-400"></i>
            <i className="fa-solid fa-chevron-right text-[8px] text-emerald-400"></i>
          </div>
        </div>

        {/* Soft Glow Effect behind the blinking text */}
        <div className="absolute inset-0 w-32 h-32 bg-emerald-500/10 blur-3xl rounded-full -z-10 animate-pulse"></div>
      </div>

      <div className="flex" ref={scrollRef}>
        {/* Double the array for seamless infinite scroll */}
        {[...IMAGES, ...IMAGES].map((src, idx) => (
          <div key={idx} className="flex-shrink-0 w-[300px] md:w-[450px] px-4">
            <div className="aspect-[4/5] overflow-hidden rounded-[2rem] shadow-2xl group relative border border-white/5">
              <img 
                src={src} 
                alt={`Wildlife ${idx}`} 
                className="w-full h-full object-cover grayscale transition-all duration-700 group-hover:grayscale-0 group-hover:scale-105 opacity-60 group-hover:opacity-100"
              />
              {/* Subtle hover overlay for the image itself */}
              <div className="absolute inset-0 bg-emerald-500/0 group-hover:bg-emerald-500/5 transition-all duration-700"></div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ScrollingGallery;

