import React, { useState, useEffect, useRef } from 'react';

interface DraggableCardProps {
  point: {
    id: string;
    icon: string;
    title: string;
    subtitle: string;
    description: string;
    extra: string;
  };
  idx: number;
}

const DraggableCard: React.FC<DraggableCardProps> = ({ point, idx }) => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const startPos = useRef({ x: 0, y: 0 });
  const cardRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = (e: React.MouseEvent) => {
    // If minimized, clicking should maximize it instead of dragging (handled in onClick)
    if (isMinimized) return;

    setIsDragging(true);
    startPos.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y
    };
    e.preventDefault();
  };

  const toggleMinimize = (e: React.MouseEvent) => {
    e.stopPropagation();
    setIsMinimized(!isMinimized);
    if (!isMinimized) {
      // When minimizing, reset drag position so it goes to the "dock" corner
      setPosition({ x: 0, y: 0 });
    }
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging || isMinimized) return;

      const newX = e.clientX - startPos.current.x;
      const newY = e.clientY - startPos.current.y;
      setPosition({ x: newX, y: newY });
    };

    const handleMouseUp = () => {
      if (isDragging) {
        setIsDragging(false);
      }
    };

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging, isMinimized]);

  // Styles for the minimized state (Corner docking)
  const minimizedStyle: React.CSSProperties = isMinimized ? {
    position: 'absolute',
    bottom: '20px',
    right: `${20 + (idx * 70)}px`, // Stack bubbles in the corner
    width: '60px',
    height: '60px',
    padding: '0',
    borderRadius: '100px',
    transform: 'translate(0, 0)',
    zIndex: 100,
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center'
  } : {
    transform: `translate(${position.x}px, ${position.y}px)`,
    zIndex: isDragging ? 50 : 10
  };

  return (
    <div 
      ref={cardRef}
      onMouseDown={handleMouseDown}
      onClick={() => isMinimized && setIsMinimized(false)}
      className={`group relative overflow-hidden backdrop-blur-3xl border border-white/10 select-none
        ${isMinimized ? 'bg-emerald-600 shadow-[0_10px_30px_rgba(16,185,129,0.5)] border-emerald-400/50 scale-100 hover:scale-110' : 'p-12 rounded-[4rem] bg-white/[0.03]'}
        ${isDragging ? 'cursor-grabbing scale-[1.05] shadow-[0_60px_100px_-20px_rgba(16,185,129,0.4)]' : 'cursor-grab hover:bg-emerald-500/[0.08] hover:border-emerald-500/40 hover:scale-[1.02]'} 
        ${!isDragging ? 'transition-all duration-700 cubic-bezier(0.175, 0.885, 0.32, 1.275)' : ''}
        ${!isMinimized && idx % 2 !== 0 ? 'md:mt-24' : ''}`}
      style={minimizedStyle}
    >
      {/* Minimize Button */}
      {!isMinimized && (
        <button 
          onClick={toggleMinimize}
          className="absolute top-8 right-8 w-8 h-8 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white/40 hover:bg-white/10 hover:text-white transition-all z-20"
          title="Minimize Card"
        >
          <i className="fa-solid fa-minus text-[10px]"></i>
        </button>
      )}

      {/* Content - Minimized only shows icon */}
      <div className={`flex flex-col items-center justify-center w-full h-full ${isMinimized ? '' : 'relative z-10 pointer-events-none'}`}>
        <div className={`flex items-center justify-center text-emerald-400 transition-all duration-500
          ${isMinimized ? 'w-full h-full bg-transparent text-white' : 'w-20 h-20 bg-emerald-500/10 rounded-3xl mb-12 group-hover:bg-emerald-500 group-hover:text-white shadow-2xl group-hover:shadow-emerald-500/40'}
        `}>
          <i className={`fa-solid ${point.icon} ${isMinimized ? 'text-xl' : 'text-3xl animate-pulse'}`}></i>
        </div>

        {!isMinimized && (
          <>
            {/* Oversized Manuscript Numeral */}
            <span className="absolute -right-10 -bottom-10 text-[200px] font-serif font-bold text-white/[0.02] group-hover:text-emerald-500/[0.06] transition-all duration-1000 select-none pointer-events-none transform group-hover:scale-110 group-hover:-rotate-12">
              {point.id}
            </span>

            <p className="text-[9px] font-bold text-emerald-400/40 tracking-[0.5em] uppercase mb-4 group-hover:text-emerald-400 transition-colors">
              {point.subtitle}
            </p>
            <h3 className="text-3xl font-serif text-white mb-8 group-hover:text-emerald-300 transition-colors leading-tight">
              {point.title}
            </h3>

            <p className="text-[14px] leading-[2.1] text-white/60 font-light mb-12 group-hover:text-white/90 transition-all duration-500">
              {point.description}
            </p>

            <div className="flex items-center gap-5">
              <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,1)] animate-ping-slow"></div>
              <span className="text-[10px] font-bold tracking-[0.3em] text-white/80 group-hover:text-emerald-400 uppercase transition-colors">
                {point.extra}
              </span>
            </div>
          </>
        )}
      </div>

      {/* Interior Hover Glow Layer */}
      {!isMinimized && (
        <div className="absolute inset-0 bg-gradient-to-tr from-emerald-500/0 via-emerald-500/[0.02] to-emerald-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none"></div>
      )}
    </div>
  );
};

