        <div className="absolute inset-0 bg-gradient-to-tr from-emerald-500/0 via-emerald-500/[0.02] to-emerald-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none"></div>
      )}
    </div>
  );
};

