import React, { useState, useEffect, useRef } from 'react';

interface InfoPoint {
  id: string;
  icon: string;
  title: string;
  subtitle: string;
  description: string;
  extra: string;
}

interface DraggableCardProps {
  point: InfoPoint;
  idx: number;
  onMinimize: (id: string) => void;
  isMinimized: boolean;
}

const DraggableCard: React.FC<DraggableCardProps> = ({ point, idx, onMinimize, isMinimized }) => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const startPos = useRef({ x: 0, y: 0 });
  const cardRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isMinimized) return;
    setIsDragging(true);
    startPos.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y
    };
    e.preventDefault();
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging) return;
      const newX = e.clientX - startPos.current.x;
      const newY = e.clientY - startPos.current.y;
      setPosition({ x: newX, y: newY });
    };

    const handleMouseUp = () => {
      if (isDragging) setIsDragging(false);
    };

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  if (isMinimized) return null;

  return (
    <div 
      ref={cardRef}
      onMouseDown={handleMouseDown}
      className={`group relative overflow-hidden backdrop-blur-3xl border border-white/10 select-none p-10 rounded-[3.5rem] bg-white/[0.03]
        ${isDragging ? 'cursor-grabbing scale-[1.05] shadow-[0_60px_100px_-20px_rgba(16,185,129,0.4)] z-50' : 'cursor-grab hover:bg-emerald-500/[0.08] hover:border-emerald-500/40 hover:scale-[1.02] z-10'} 
        ${!isDragging ? 'transition-all duration-1000 cubic-bezier(0.175, 0.885, 0.32, 1.275)' : ''}
        ${idx % 2 !== 0 ? 'md:mt-16' : ''}`}
      style={{ transform: `translate(${position.x}px, ${position.y}px)` }}
    >
      {/* MINUS BUTTON & CAPTION */}
      <div className="absolute top-6 right-6 flex flex-col items-end gap-2 z-20 pointer-events-auto">
        <button 
          onClick={(e) => { e.stopPropagation(); onMinimize(point.id); }}
          className="w-10 h-10 rounded-full bg-white/5 border border-white/10 flex items-center justify-center text-white/40 hover:bg-red-500/40 hover:text-white transition-all shadow-lg backdrop-blur-md"
          title="Minimize to Rail"
        >
          <i className="fa-solid fa-minus text-[14px] animate-blink"></i>
        </button>
        <span className="text-[7px] font-bold text-emerald-400 opacity-0 group-hover:opacity-100 tracking-[0.3em] uppercase transition-opacity whitespace-nowrap select-none">
          Click to Dock
        </span>
      </div>

      <div className="flex flex-col items-center justify-center w-full h-full relative z-10 pointer-events-none">
        <div className="flex items-center justify-center transition-all duration-500 w-16 h-16 bg-emerald-500/10 rounded-2xl mb-8 group-hover:bg-emerald-500 group-hover:text-white shadow-xl group-hover:shadow-emerald-500/40">
          <i className={`fa-solid ${point.icon} text-2xl animate-pulse`}></i>
        </div>

        <span className="absolute -right-6 -bottom-6 text-[150px] font-serif font-bold text-white/[0.01] group-hover:text-emerald-500/[0.04] transition-all duration-1000 select-none pointer-events-none transform group-hover:scale-110">
          {point.id}
        </span>

        <p className="text-[8px] font-bold text-emerald-400/40 tracking-[0.5em] uppercase mb-3 group-hover:text-emerald-400 transition-colors">
          {point.subtitle}
        </p>
        <h3 className="text-2xl font-serif text-white mb-6 group-hover:text-emerald-300 transition-colors leading-tight text-center">
          {point.title}
        </h3>

        <p className="text-[13px] leading-[1.8] text-white/60 font-light mb-8 group-hover:text-white/90 transition-all duration-500 text-center">
          {point.description}
        </p>

        <div className="flex items-center gap-4">
          <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 shadow-[0_0_10px_rgba(16,185,129,1)] animate-ping-slow"></div>
          <span className="text-[9px] font-bold tracking-[0.3em] text-white/80 group-hover:text-emerald-400 uppercase transition-colors">
            {point.extra}
          </span>
        </div>
      </div>

      <div className="absolute inset-0 bg-gradient-to-tr from-emerald-500/0 via-emerald-500/[0.02] to-emerald-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none"></div>
    </div>
  );
};

