import React, { useState, useEffect, useRef } from 'react';

interface InfoPoint {
  id: string;
  icon: string;
  title: string;
  subtitle: string;
  description: string;
  extra: string;
}

interface DraggableCardProps {
  point: InfoPoint;
  idx: number;
  onMinimize: (id: string) => void;
  isMinimized: boolean;
  isFocused: boolean;
  onFocus: (id: string) => void;
}

const DraggableCard: React.FC<DraggableCardProps> = ({ point, idx, onMinimize, isMinimized, isFocused, onFocus }) => {
  const [position, setPosition] = useState({ x: 0, y: 0 });
  const [isDragging, setIsDragging] = useState(false);
  const startPos = useRef({ x: 0, y: 0 });
  const cardRef = useRef<HTMLDivElement>(null);

  const handleMouseDown = (e: React.MouseEvent) => {
    if (isMinimized || isFocused) return;
    setIsDragging(true);
    startPos.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y
    };
    e.preventDefault();
  };

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (!isDragging) return;
      const newX = e.clientX - startPos.current.x;
      const newY = e.clientY - startPos.current.y;
      setPosition({ x: newX, y: newY });
    };

    const handleMouseUp = () => {
      if (isDragging) setIsDragging(false);
    };

    if (isDragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
    }
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
    };
  }, [isDragging]);

  const genieStyle: React.CSSProperties = isMinimized ? {
    transform: `translate(-400px, ${idx * 30}px) scale(0) rotate(-10deg)`,
    opacity: 0,
    pointerEvents: 'none',
    filter: 'blur(20px)',
    position: 'absolute',
    width: '100%'
  } : {
    transform: `translate(${position.x}px, ${position.y}px) scale(1) rotate(0deg)`,
    opacity: 1,
    position: 'relative',
    gridColumn: isFocused ? 'span 2 / span 2' : 'auto'
  };

  return (
    <div 
      ref={cardRef}
      onMouseDown={handleMouseDown}
      onClick={() => !isMinimized && onFocus(point.id)}
      className={`group overflow-hidden backdrop-blur-3xl border select-none transition-all duration-700
        ${isFocused ? 'bg-[#D1FAE5] border-emerald-500/50 p-12 md:p-20 rounded-[4rem] shadow-[0_0_120px_rgba(16,185,129,0.3)] z-30 cursor-default' : 'bg-white/[0.03] border-white/10 p-10 rounded-[3.5rem] z-10 cursor-pointer'}
        ${isDragging ? 'cursor-grabbing scale-[1.05] shadow-[0_60px_100px_-20px_rgba(16,185,129,0.4)] z-50 transition-none' : 'hover:bg-emerald-500/[0.08] hover:border-emerald-500/40 hover:scale-[1.02]'} 
        ${!isDragging ? 'cubic-bezier(0.6, -0.28, 0.735, 0.045)' : ''}
        ${idx % 2 !== 0 && !isFocused && !isMinimized ? 'md:mt-16' : ''}
        ${isMinimized ? 'invisible h-0 overflow-hidden' : 'visible min-h-[400px]'}`}
      style={genieStyle}
    >
      {/* MINUS BUTTON (DOCK) */}
      <div className="absolute top-8 right-8 flex flex-col items-end gap-2 z-20 pointer-events-auto">
        <button 
          onClick={(e) => { e.stopPropagation(); onMinimize(point.id); }}
          className={`w-12 h-12 rounded-full border flex items-center justify-center transition-all shadow-lg backdrop-blur-md ${isFocused ? 'bg-[#064E3B]/10 border-[#064E3B]/20 text-[#064E3B] hover:bg-red-500/80 hover:text-white' : 'bg-white/5 border-white/10 text-white/40 hover:bg-red-500/40 hover:text-white'}`}
          title="Minimize to Rail"
        >
          <i className="fa-solid fa-minus text-[16px] animate-blink"></i>
        </button>
        <span className={`text-[7px] font-bold opacity-0 group-hover:opacity-100 tracking-[0.3em] uppercase transition-opacity whitespace-nowrap select-none ${isFocused ? 'text-[#064E3B]/40 group-hover:text-emerald-600' : 'text-emerald-400'}`}>
          Click to Dock
        </span>
      </div>

      <div className={`flex flex-col items-center justify-center w-full h-full relative z-10 pointer-events-none transition-all duration-700 ${isFocused ? 'scale-105' : 'scale-100'}`}>
        <div className={`flex items-center justify-center transition-all duration-500 rounded-2xl mb-8 group-hover:bg-emerald-500 group-hover:text-white shadow-xl group-hover:shadow-emerald-500/40 ${isFocused ? 'w-24 h-24 text-3xl bg-[#064E3B] text-white' : 'w-16 h-16 text-2xl bg-emerald-500/10 text-emerald-400'}`}>
          <i className={`fa-solid ${point.icon} ${!isFocused ? 'animate-pulse' : ''}`}></i>
        </div>

        <span className={`absolute -right-6 -bottom-6 font-serif font-bold transition-all duration-1000 select-none pointer-events-none transform group-hover:scale-110 ${isFocused ? 'text-[#064E3B]/[0.05] text-[350px]' : 'text-white/[0.01] text-[150px]'}`}>
          {point.id}
        </span>

        {/* Subtitle with light hover color for max view */}
        <p className={`font-bold tracking-[0.5em] uppercase mb-3 transition-colors ${isFocused ? 'text-emerald-800/80 group-hover:text-emerald-500 text-[12px]' : 'text-emerald-400/40 group-hover:text-emerald-400 text-[8px]'}`}>
          {point.subtitle}
        </p>

        {/* Title with light hover color for max view */}
        <h3 className={`font-serif mb-6 transition-colors leading-tight text-center ${isFocused ? 'text-[#064E3B] group-hover:text-emerald-600 text-5xl md:text-7xl' : 'text-white group-hover:text-emerald-300 text-2xl'}`}>
          {point.title}
        </h3>

        {/* Description with light hover color for max view */}
        <p className={`leading-[2] font-light mb-8 transition-all duration-500 text-center max-w-2xl ${isFocused ? 'text-[#064E3B]/70 group-hover:text-emerald-700 text-lg md:text-2xl italic' : 'text-white/60 group-hover:text-white/90 text-[13px]'}`}>
          {point.description}
        </p>

        <div className="flex items-center gap-4">
          <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_15px_rgba(16,185,129,1)] animate-ping-slow"></div>
          <span className={`font-bold tracking-[0.3em] uppercase transition-colors ${isFocused ? 'text-[#064E3B]/80 group-hover:text-emerald-600 text-[12px]' : 'text-white/80 group-hover:text-emerald-400 text-[9px]'}`}>
            {point.extra}
          </span>
        </div>

        {isFocused && (
          <button 
            onClick={(e) => { e.stopPropagation(); onMinimize(point.id); }}
            className="mt-12 px-10 py-5 bg-[#064E3B] text-white rounded-2xl font-bold text-[10px] tracking-[0.3em] uppercase hover:bg-emerald-600 hover:scale-105 transition-all shadow-2xl pointer-events-auto active:scale-95"
          >
            EXIT FOCUS MODE
          </button>
        )}
      </div>

      {!isFocused && <div className="absolute inset-0 bg-gradient-to-tr from-emerald-500/0 via-emerald-500/[0.02] to-emerald-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-700 pointer-events-none"></div>}
    </div>
  );
};

