                onClick={() => {
                  if (isPast) return;
                  setError(null);
                  if (!startDate || (startDate && endDate)) {
                    setStartDate(date);
                    setEndDate(null);
                  } else {
                    if (date < startDate) { 
                      setStartDate(date); 
                      setEndDate(null); 
                    } else if (date.toDateString() !== startDate.toDateString()) { 
                      setEndDate(date); 
                    }
                  }
