              className="h-20 bg-emerald-600 px-10 text-[11px] font-bold tracking-[0.3em] uppercase hover:bg-white hover:text-[#064E3B] transition-all whitespace-nowrap shadow-xl text-white w-full md:w-auto mt-6 md:mt-0 flex items-center justify-center gap-3 group"
            >
              <span>CHECK AVAILABILITY</span>
